import { describe, it, expect } from "bun:test";
import { parseSse, SseParser } from "@utils/sse-parser.ts";
import { makeRng, randomChunksBytes, codePoints, type Rng } from "../fuzz/prng.ts";

// Fuzz suite for the SSE parser (untrusted network input). Invariants, audited on
// EVERY generated stream, not fixed samples:
//
//   1. Split equivalence: for any generated byte stream and any chunk split
//      (random, adversarial-boundary, byte-at-a-time, cuts after every CR / LF),
//      the emitted event sequence AND the warning sequence are IDENTICAL to a
//      single-feed parse. Chunk boundaries must never change semantics -- in
//      particular a CRLF torn between CR and LF must not inject a phantom blank
//      line (that reset `currentEvent` early and leaked suppressed data; see the
//      regression case and the `pendingCR` fix in src/utils/sse-parser.ts).
//   2. No crashes: parsing always terminates; malformed bytes never throw out of
//      the generator (a throw is recorded and asserted, not swallowed).
//   3. Incomplete trailing input: a data line with no line terminator at EOF
//      never fires; a stream ending in CR still fires everything the CR
//      terminated; completed events are never swallowed.
//   4. Line-size guard seam: `SseParserOptions.maxJsonBuffer` (default
//      DEFAULT_MAX_JSON_BUFFER = 500_000 chars) is a public option, so the guard
//      is fuzzed at small configured limits; the literal default gets a few
//      exact-boundary probes (~0.5MB each, never 200MB-class allocations).
//      Real behavior pinned here: when accumulated malformed fragments exceed
//      the limit on a failed re-parse, the parser WARNS and DISCARDS the buffer
//      (no error thrown); the check is strict `>`, so exactly-at stays alive and
//      can still be completed; [DONE] flushes (parse or warn), resetting state.
//
// Real pinned semantics the differential relies on (from src/utils/sse-parser.ts):
// yields fire per `data:` line (no blank-line dispatch); lines are trim()ed
// before field matching; non-object JSON warns and is dropped; data lines in a
// non-"message" event block are suppressed until the next blank line; failed
// parses accumulate into jsonBuffer across data lines and re-parse on each add.

const enc = new TextEncoder();

interface ParseRun {
  events: unknown[];
  warnings: string[];
  threw: string | null;
}

async function runParse(
  chunks: Uint8Array[],
  options?: { maxJsonBuffer?: number },
): Promise<ParseRun> {
  const events: unknown[] = [];
  const warnings: string[] = [];
  try {
    const stream = new ReadableStream<Uint8Array>({
      start(c) {
        for (const ch of chunks) c.enqueue(ch);
        c.close();
      },
    });
    for await (const ev of parseSse(stream, {
      maxJsonBuffer: options?.maxJsonBuffer,
      onWarning: (m) => warnings.push(m),
    })) {
      events.push(ev);
    }
  } catch (e) {
    return { events, warnings, threw: `${(e as Error).constructor.name}: ${(e as Error).message}` };
  }
  return { events, warnings, threw: null };
}

// ── Split helpers ───────────────────────────────────────────────────

function cutAfterBytes(bytes: Uint8Array, pred: (b: number) => boolean): Uint8Array[] {
  const pieces: Uint8Array[] = [];
  let at = 0;
  for (let i = 0; i < bytes.length; i++) {
    if (pred(bytes[i]!)) {
      pieces.push(bytes.subarray(at, i + 1));
      at = i + 1;
    }
  }
  pieces.push(bytes.subarray(at));
  return pieces;
}

function byteAtATime(bytes: Uint8Array): Uint8Array[] {
  const out: Uint8Array[] = [];
  for (let i = 0; i < bytes.length; i++) out.push(bytes.subarray(i, i + 1));
  if (out.length === 0) out.push(bytes);
  return out;
}

// ── Seeded generator ────────────────────────────────────────────────

const DATA_PREFIXES = ["data:", "data: ", "data:  ", "  data:", "data:\t", "DATA:", "data"] as const;

const UNICODE_BITS = [
  "\u{1F600}",
  "\u{1F1E6}\u{1F1FF}",
  "\u6F22\u5B57",
  "\u{1F4A9}x",
  "e\u0301",
  "\u{2E7F}",
  "\uFEFF",
] as const;

const NOISE_CHARS: string[] = [];
for (const cp of codePoints(0x20, 0x2ff)) NOISE_CHARS.push(String.fromCodePoint(cp));
for (const cp of codePoints(0x1f300, 0x1f350)) NOISE_CHARS.push(String.fromCodePoint(cp));

function genStringValue(rng: Rng): string {
  const shapes = [
    "plain",
    "",
    "a\\rb", // literal backslash-r escape shape
    "a\\nb tail",
    "tab\there", // raw control: JSON.stringify escapes it
    "crlf\r\nshape", // raw control: JSON.stringify escapes it
    "data: fake",
    "x] 9",
    "line\u2028sep",
    'quote"inside',
    "back\\\\slash",
    rng.pick(UNICODE_BITS)!,
    rng.pick(UNICODE_BITS)! + rng.pick(UNICODE_BITS)!,
  ];
  return rng.pick(shapes)!;
}

function genJsonValue(rng: Rng, depth: number): unknown {
  const kinds = depth < 2 ? 7 : 5;
  const roll = rng.int(kinds);
  if (roll === 0) return rng.int(1000);
  if (roll === 1) return rng.bool();
  if (roll === 2) return null;
  if (roll === 3) return genStringValue(rng);
  if (roll === 4) {
    const n = rng.int(4);
    const arr: unknown[] = [];
    for (let i = 0; i < n; i++) arr.push(genJsonValue(rng, depth + 1));
    return arr;
  }
  const n = rng.int(4);
  const obj: Record<string, unknown> = {};
  for (let i = 0; i < n; i++) obj[`k${i}${rng.bool() ? rng.pick(UNICODE_BITS)! : ""}`] = genJsonValue(rng, depth + 1);
  return obj;
}

function genObjPayload(rng: Rng): string {
  let v = genJsonValue(rng, 0);
  if (v === null || typeof v !== "object" || Array.isArray(v)) v = { v };
  return JSON.stringify(v);
}

// One "group" of lines (no terminators) -- usually one line, sometimes a
// multi-line JSON fragment set that the parser must reassemble via jsonBuffer.
function genLineGroup(rng: Rng): string[] {
  const roll = rng.int(100);
  if (roll < 22) return [rng.pick(DATA_PREFIXES)! + genObjPayload(rng)];
  if (roll < 30) return [rng.pick(DATA_PREFIXES)! + rng.pick(["1", "42.5", '"a string"', "[1,2]", "null", "true", "[]"])!];
  if (roll < 36) return [rng.pick(["data:[DONE]", "data: [DONE]", "data:  [DONE]", "data: [done]"])!];
  if (roll < 50) {
    const g = rng.pick(["{", '{"a"', "[1", "}{", "a", '"', "{,}", '"unterminated', "nullz", '{"a":}', "NaN", "'sq'", ""])!;
    return [rng.pick(DATA_PREFIXES)! + g];
  }
  if (roll < 58) {
    // Split one JSON object across 2-3 data lines: exercises the fragment
    // accumulator, including cuts through surrogate pairs.
    const payload = genObjPayload(rng);
    const pieces = Math.min(payload.length, 2 + rng.int(2));
    const bounds: number[] = [];
    while (bounds.length < pieces - 1) {
      const b = 1 + rng.int(payload.length - 1);
      if (!bounds.includes(b)) bounds.push(b);
    }
    bounds.sort((a, b) => a - b);
    const out: string[] = [];
    let at = 0;
    for (const b of bounds) {
      out.push("data:" + payload.slice(at, b));
      at = b;
    }
    out.push("data:" + payload.slice(at));
    return out;
  }
  if (roll < 64) return [rng.pick([": ping", ":", ":comment", ":: weird", ": [DONE]"])!];
  if (roll < 74) {
    return [rng.pick(["event: sig", "event: message", "event:no-space", "event:  dbl", "Event: x", "event:", "event: [DONE]"])!];
  }
  if (roll < 84) {
    return [rng.pick(["id: 7", "retry: 500", "foo: bar", "x", 'data2: {"a":1}', "Data:1", "d ata: 1"])!];
  }
  if (roll < 92) return [""];
  const n = 1 + rng.int(24);
  let s = "";
  for (let i = 0; i < n; i++) s += rng.pick(NOISE_CHARS)!;
  return [s];
}

function genStream(rng: Rng): string {
  if (rng.bool(0.04)) return "";
  const parts: string[] = [];
  if (rng.bool(0.1)) parts.push("\uFEFF"); // BOM at stream head
  if (rng.bool(0.1)) parts.push(rng.pick(["\n", "\r\n", "\n\n", "\r"])!); // leading blank lines
  const groups = 1 + rng.int(10);
  for (let g = 0; g < groups; g++) {
    for (const line of genLineGroup(rng)) {
      parts.push(line, rng.pick(["\n", "\n", "\r\n", "\r"])!);
    }
  }
  if (rng.bool(0.25)) {
    const last = parts[parts.length - 1]!;
    if (last === "\n" || last === "\r\n" || last === "\r") parts.pop(); // incomplete trailing line
  }
  if (rng.bool(0.08)) parts.push(rng.pick(["\r", "\n\r", "\r\r"])!); // stream ending on CR
  return parts.join("");
}

// ── Core differential ───────────────────────────────────────────────

describe("sse-parser fuzz", () => {
  it("any chunk split yields events AND warnings identical to a single-feed parse", async () => {
    const rng = makeRng(0x55e5ba11);
    const ITERS = 350;
    const failures: { iter: number; stream: string; mode: string; ref: string; got: string }[] = [];

    for (let i = 0; i < ITERS; i++) {
      const stream = genStream(rng);
      const bytes = enc.encode(stream);
      const ref = await runParse([bytes]);
      const modes: [string, Uint8Array[]][] = [
        ["random", randomChunksBytes(rng, bytes, 1 + rng.int(6), "random")],
        ["adversarial", randomChunksBytes(rng, bytes, 8, "adversarial")],
        ["cr-cuts", cutAfterBytes(bytes, (b) => b === 0x0d)],
        ["lf-cuts", cutAfterBytes(bytes, (b) => b === 0x0a)],
      ];
      if (bytes.length > 0 && bytes.length <= 400) modes.push(["bytes", byteAtATime(bytes)]);

      for (const [mode, chunks] of modes) {
        const got = await runParse(chunks);
        if (got.threw !== null || ref.threw !== null || !sameRun(ref, got)) {
          failures.push({
            iter: i,
            stream: JSON.stringify(stream),
            mode,
            ref: JSON.stringify(ref),
            got: JSON.stringify(got),
          });
        }
      }
      if (failures.length >= 3) break;
    }

    expect(failures).toEqual([]);
  }, 30_000);

  it("SseParser class matches the parseSse factory under chunking", async () => {
    const rng = makeRng(0xc1a55007);
    for (let i = 0; i < 60; i++) {
      const stream = genStream(rng);
      const bytes = enc.encode(stream);
      const ref = await runParse([bytes]);
      const chunks = randomChunksBytes(rng, bytes, 6, rng.bool() ? "adversarial" : "random");
      const warnings: string[] = [];
      const events: unknown[] = [];
      const s = new ReadableStream<Uint8Array>({
        start(c) {
          for (const ch of chunks) c.enqueue(ch);
          c.close();
        },
      });
      for await (const ev of new SseParser({ onWarning: (m) => warnings.push(m) }).parse(s)) {
        events.push(ev);
      }
      expect(JSON.stringify({ events, warnings, threw: null })).toBe(JSON.stringify(ref));
    }
  });

  // Regression for the phantom-blank-line bug: the held trailing CR used to be
  // re-prepended to the buffer and re-split as a standalone terminator, so a
  // split between CR and LF injected a blank line, reset currentEvent early,
  // and leaked data from a suppressed (non-message) event block.
  it("CRLF torn between CR and LF never leaks suppressed event data", async () => {
    const s = 'event: foo\r\ndata: {"x":1}\r\n\r\ndata: {"y":2}\n\n';
    const bytes = enc.encode(s);
    const ref = await runParse([bytes]);
    expect(ref.events).toEqual([{ y: 2 }]); // {x:1} belongs to event "foo": suppressed
    expect(ref.threw).toBeNull();

    const variants: Uint8Array[][] = [];
    for (let i = 1; i < bytes.length; i++) {
      if (bytes[i - 1] === 0x0d) variants.push([bytes.subarray(0, i), bytes.subarray(i)]);
    }
    variants.push(byteAtATime(bytes));
    for (const chunks of variants) {
      const got = await runParse(chunks);
      expect(got.threw).toBeNull();
      expect(JSON.stringify(got)).toBe(JSON.stringify(ref));
    }
  });
});

// ── Trailing-incompleteness sweep ───────────────────────────────────

describe("sse-parser trailing edges", () => {
  const BODIES = [
    'data: {"a":1}',
    'data: {"a":1}\n\ndata: {"b":2}',
    "data: {\"a\":1}\r\ndata: [DONE]",
    'data: {"p":',
    'data: {"p":1}',
    'data: {"a":1}\nevent: tail',
  ];
  const TAILS = ["", "\n", "\r", "\n\n", "\r\n", "\r\r", "\n\r"];

  it("every body x trailing x split combination matches the single-feed parse", async () => {
    const rng = makeRng(0x7a110e05);
    const mismatches: { body: string; tail: string; mode: string; ref: string; got: string }[] = [];
    for (const body of BODIES) {
      for (const tail of TAILS) {
        const bytes = enc.encode(body + tail);
        const ref = await runParse([bytes]);
        const modes: [string, Uint8Array[]][] = [
          ["adversarial", randomChunksBytes(rng, bytes, 7, "adversarial")],
          ["bytes", byteAtATime(bytes)],
          ["cr-cuts", cutAfterBytes(bytes, (b) => b === 0x0d)],
        ];
        for (const [mode, chunks] of modes) {
          const got = await runParse(chunks);
          if (got.threw !== null || !sameRun(ref, got)) {
            mismatches.push({ body, tail, mode, ref: JSON.stringify(ref), got: JSON.stringify(got) });
          }
        }
      }
    }
    expect(mismatches).toEqual([]);
  });

  it("an un-terminated trailing data line never fires", async () => {
    expect((await runParse([enc.encode('data: {"a":1}')])).events).toEqual([]);
    expect((await runParse([enc.encode('data: {"a":1}\n\ndata: {"b":2}')])).events).toEqual([{ a: 1 }]);
  });

  it("a stream ending in CR still fires everything the CR terminated", async () => {
    for (const chunks of [[enc.encode('data: {"a":1}\r')], [enc.encode("data: {\"a\":1}"), enc.encode("\r")], byteAtATime(enc.encode('data: {"a":1}\r'))]) {
      const got = await runParse(chunks);
      expect(got.threw).toBeNull();
      expect(got.events).toEqual([{ a: 1 }]);
    }
  });
});

// ── BOM / leading-newline tolerance ─────────────────────────────────

describe("sse-parser BOM and leading-newline consistency", () => {
  it("BOM and leading blank lines behave identically under every split", async () => {
    const cases = [
      '\uFEFFdata: {"b":1}\n\ndata: {"c":2}\n\n',
      'data: {"b":1}\n\ndata: {"c":2}\n\n',
      '\n\ndata: {"b":1}\n\n',
      '\r\n\r\ndata: {"b":1}\n\n',
      '\r\uFEFFdata: {"b":1}\n\n',
    ];
    const rng = makeRng(0x800b0015);
    for (const text of cases) {
      const bytes = enc.encode(text);
      const ref = await runParse([bytes]);
      const variants: Uint8Array[][] = [
        byteAtATime(bytes),
        randomChunksBytes(rng, bytes, 5, "adversarial"),
        randomChunksBytes(rng, bytes, 4, "random"),
      ];
      for (let i = 1; i < bytes.length; i++) variants.push([bytes.subarray(0, i), bytes.subarray(i)]);
      for (const chunks of variants) {
        const got = await runParse(chunks);
        expect(got.threw).toBeNull();
        expect(JSON.stringify(got)).toBe(JSON.stringify(ref));
      }
    }
    // A head BOM must not change the events versus no BOM at all.
    const withBom = await runParse([enc.encode('\uFEFFdata: {"b":1}\n\n')]);
    const noBom = await runParse([enc.encode('data: {"b":1}\n\n')]);
    expect(withBom.events).toEqual(noBom.events);
    expect(withBom.events).toEqual([{ b: 1 }]);
  });
});

// ── Line-size guard at the seam ─────────────────────────────────────

describe("sse-parser maxJsonBuffer guard", () => {
  // Junk payloads made only of a,x,{,} -- every fragment and every accumulation
  // of them starts with "a" so it is NEVER valid JSON: the model below predicts
  // the parser's exact warn/discard sequence (jsonBuffer += payload; strict >
  // check; warn + reset).
  function junkPayload(rng: Rng, len: number): string {
    let s = "a";
    for (let i = 1; i < len; i++) s += rng.pick(["a", "x", "{", "}"])!;
    return s;
  }

  it("random probes at small limits match the model exactly (warning count, text, discards)", async () => {
    const rng = makeRng(0x60a60000);
    const ITERS = 250;
    const failures: { iter: number; L: number; payloads: string[]; expected: string[]; got: string[] }[] = [];
    for (let i = 0; i < ITERS; i++) {
      const L = 4 + rng.int(25);
      const n = 1 + rng.int(12);
      const payloads: string[] = [];
      for (let p = 0; p < n; p++) payloads.push(junkPayload(rng, 1 + rng.int(L + 3)));

      const expected: string[] = [];
      let cum = "";
      for (const p of payloads) {
        cum += p;
        if (cum.length > L) {
          expected.push(`[sse] malformed JSON (${cum.length} chars): ${cum.slice(0, 100)}...`);
          cum = "";
        }
      }
      if (cum.length > 0) expected.push(`[sse] truncated JSON at EOF (${cum.length} chars)`);

      const text = payloads.map((p) => `data:${p}\n`).join("");
      const got = await runParse([enc.encode(text)], { maxJsonBuffer: L });
      if (got.threw !== null || got.events.length !== 0 || JSON.stringify(got.warnings) !== JSON.stringify(expected)) {
        failures.push({ iter: i, L, payloads, expected, got: got.warnings });
      }
      if (failures.length >= 3) break;
    }
    expect(failures).toEqual([]);
  });

  it("accumulation at exactly the limit stays alive and can be completed", async () => {
    const L = 32;
    const full = `{"a":"${"x".repeat(L - 8)}"}`;
    expect(full.length).toBe(L);
    const first = full.slice(0, 10);
    const rest = full.slice(10);
    const text = `data:${first}\ndata:${rest}\n`;
    const got = await runParse([enc.encode(text)], { maxJsonBuffer: L });
    expect(got.warnings).toEqual([]);
    expect(got.events).toEqual([{ a: "x".repeat(L - 8) }]); // exactly-at-limit flush works
  });

  it("garbage at exactly the limit is kept, exceeding by one warns and discards, parser recovers", async () => {
    const L = 32;
    const text = `data:${"a".repeat(31)}\ndata:a\ndata:a\ndata:{"ok":true}\n`;
    // 31 -> alive, 32 -> alive (strict >), 33 -> warn + discard, then a clean object yields.
    const got = await runParse([enc.encode(text)], { maxJsonBuffer: L });
    expect(got.warnings.length).toBe(1);
    expect(got.warnings[0]).toContain("malformed JSON (33 chars)");
    expect(got.events).toEqual([{ ok: true }]);
  });

  it("default limit (500000 chars): alive at exactly, warns just over", async () => {
    // Three targeted probes at the real DEFAULT_MAX_JSON_BUFFER; ~0.5MB per
    // case, no large-loop allocation.
    const at = await runParse([enc.encode(`data:${"a".repeat(500_000)}\n`)]);
    expect(at.warnings).toEqual(["[sse] truncated JSON at EOF (500000 chars)"]); // alive, no overflow warning
    expect(at.events).toEqual([]);

    const over = await runParse([enc.encode(`data:${"a".repeat(500_001)}\n`)]);
    expect(over.warnings.length).toBe(1);
    expect(over.warnings[0]).toContain("malformed JSON (500001 chars)");

    const underThenDone = await runParse([enc.encode(`data:${"a".repeat(499_999)}\ndata: [DONE]\n`)]);
    expect(underThenDone.warnings.length).toBe(1);
    expect(underThenDone.warnings[0]).toContain("on [DONE] flush (499999 chars)");
  });

  it("[DONE] flushes a live fragment and discards garbage (state resets)", async () => {
    const L = 64;
    // Live fragments completed by the [DONE] line's own text? [DONE] is
    // handled before the accumulator, so it only flushes what came before.
    const flush = await runParse([enc.encode('data:{"a"\ndata::7}\ndata:[DONE]\n')], { maxJsonBuffer: L });
    expect(flush.events).toEqual([{ a: 7 }]); // concatenated before [DONE] arrived
    expect(flush.warnings).toEqual([]);

    const garbage = await runParse([enc.encode("data:{oops\ndata:[DONE]\ndata:{\"b\"\ndata::2}\n")], { maxJsonBuffer: L });
    expect(garbage.warnings.length).toBe(1);
    expect(garbage.warnings[0]).toContain("on [DONE] flush (5 chars)");
    expect(garbage.events).toEqual([{ b: 2 }]); // buffer was reset by [DONE]
  });
});

function sameRun(a: ParseRun, b: ParseRun): boolean {
  // threw is an own property of ParseRun, so the stringify compares it too.
  return JSON.stringify(a) === JSON.stringify(b);
}
